function registerPromptCapture(pi: ExtensionAPI): (input?: Parameters<typeof writeSessionCapture>[0]) => void {
	let latest: Parameters<typeof writeSessionCapture>[0] | undefined;
	pi.on("before_provider_request", (event) => {
		if (!latest) return;
		const providerSystemPrompt = extractProviderSystemPrompt(event.payload);
		if (!providerSystemPrompt) return;
		try {
			writeSessionCapture({ ...latest, effectiveSystemPrompt: providerSystemPrompt });
		} catch {
			/* capture is best-effort */
		}
	});
	return (input) => {
		latest = input;
	};
}

function registerSubagentOverlay(pi: ExtensionAPI, harnessName: HarnessName | typeof PI_DEFAULT): void {
	registerCapturePrune(pi);
	const capturePrompt = registerPromptCapture(pi);
	pi.on("before_agent_start", async (event, ctx) => {
		const resolved: ResolvedHarness | undefined = isPiDefault(harnessName)
			? undefined
			: {
					name: harnessName,
					model: ctx.model ? `${ctx.model.provider}/${ctx.model.id}` : undefined,
					thinking: pi.getThinkingLevel() as ThinkingLevel,
					source: "session",
				};
		const overlay = resolved ? renderOverlay(resolved) : "";
		const effectiveSystemPrompt =
			overlay && !event.systemPrompt.includes(OVERLAY_MARK)
				? `${event.systemPrompt}\n\n${overlay}`
				: event.systemPrompt;
		if (loadSessionCaptureEnabled()) {
			const { sessionId, ephemeral } = captureSessionMeta(ctx, process.env.PI_SUBAGENT_PARENT_SESSION_ID);
			capturePrompt({
				sessionId,
				captureSubdir: process.env.PI_SUBAGENT_CAPTURE_SUBDIR,
				cwd: ctx.cwd,
				trusted: ctx.isProjectTrusted(),
				harnessName,
				harnessOverlay: overlay,
				effectiveSystemPrompt,
				model: ctx.model,
				thinking: String(pi.getThinkingLevel()),
				ephemeral,
			});
		}
		if (effectiveSystemPrompt === event.systemPrompt) return;
		return { systemPrompt: effectiveSystemPrompt };
	});
}

export default function (pi: ExtensionAPI): void {
	if (process.env.PI_SUBAGENT === "1") {
		const harnessName = subagentHarnessFromEnvironment();
		if (harnessName) registerSubagentOverlay(pi, harnessName);
		return;
	}
	registerCapturePrune(pi);
	const capturePrompt = registerPromptCapture(pi);

	pi.registerCommand("harness", {
		description: "Open harness picker, or switch with /harness:<name>",
		getArgumentCompletions: (prefix) => {
			const needle = prefix.trim().toLowerCase();
			const items = [autoCommand(autoRoute), "list", ...HARNESS_NAMES]
				.filter((name) => name.startsWith(needle))
				.map((name) => ({ value: name, label: name }));
			return items.length > 0 ? items : null;
		},
		handler: async (args, ctx) => handleHarnessCommand(pi, args, ctx),
	});
	// One slash command, named for the direction it applies. Pi fixes the command list at load, so
	// the name comes from the startup config: `auto: "off"` registers `on`, anything else `off`.
	const startupAuto = autoCommand(loadHarnessConfig().auto);
	pi.registerCommand(harnessCommand(startupAuto), {
		description:
			startupAuto === AUTO_ON
				? "Turn automatic harness selection on (route by model)"
				: "Turn automatic harness selection off (no overlay)",
		handler: async (_args, ctx) => handleHarnessCommand(pi, startupAuto, ctx),
	});
	for (const name of HARNESS_NAMES) {
		pi.registerCommand(harnessCommand(name), {
			description: `Switch to ${name}`,
			handler: async (_args, ctx) => handleHarnessCommand(pi, name, ctx),
		});
	}

	pi.on("session_start", async (_event, ctx) => {
		applyStartupSelection(ctx.model);
		publishHarnessState();
		const resolved = current();
		if (resolved) await applyGrade(pi, ctx, resolved);
		refreshStatus(ctx);
	});

	pi.on("model_select", async (event, ctx) => {
		if (applying) return;
		if (!snapshot) captureSnapshot(pi, ctx);
		if (!snapshot) return;
		snapshot = {
			...snapshot,
			model: event.model,
			thinking: pi.getThinkingLevel() as ThinkingLevel,
		};
		if (!autoRoute) return;

		const previous = activeName();
		const selected = routeHarnessForModel(event.model, loadHarnessConfig());
		sessionEnabled = !isPiDefault(selected);
		sessionName = sessionEnabled ? (selected as HarnessName) : undefined;
		sessionUsesSelectedModel = true;
		publishHarnessState();

		const resolved = current();
		if (resolved) await applyGrade(pi, ctx, resolved);
		else await restore(pi);
		refreshStatus(ctx);
		if (ctx.hasUI && event.source !== "restore" && activeName() !== previous) {
			ctx.ui.notify(`Model route: ${harnessLabel(activeName())}`, "info");
		}
	});

	pi.on("thinking_level_select", async (event, ctx) => {
		if (applying) return;
		if (!snapshot) captureSnapshot(pi, ctx);
		else snapshot = { ...snapshot, thinking: event.level as ThinkingLevel };
	});

	pi.on("before_agent_start", async (event, ctx) => {
		const resolved = current();
		if (!resolved) {
			capturePrompt();
			return;
		}
		recordHarnessUse(resolved.name);
		applyTools(pi, resolved.name);
		const overlay = renderOverlay(resolved);
		const effectiveSystemPrompt = event.systemPrompt.includes(OVERLAY_MARK)
			? event.systemPrompt
			: `${event.systemPrompt}\n\n${overlay}`;
		if (loadSessionCaptureEnabled()) {
			const { sessionId, ephemeral } = captureSessionMeta(ctx);
			capturePrompt({
				sessionId,
				cwd: ctx.cwd,
				trusted: ctx.isProjectTrusted(),
				harnessName: resolved.name,
				harnessOverlay: overlay,
				effectiveSystemPrompt,
				model: ctx.model,
				thinking: String(pi.getThinkingLevel()),
				ephemeral,
			});
		}
		if (effectiveSystemPrompt === event.systemPrompt) return;
		return { systemPrompt: effectiveSystemPrompt };
	});
}

