		if (applying) return;
		if (!snapshot) captureSnapshot(pi, ctx);
		else snapshot = { ...snapshot, thinking: event.level as ThinkingLevel };
	});

	pi.on("before_agent_start", async (event, ctx) => {
		const resolved = current();
