import assert from "node:assert/strict";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, statSync, utimesSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import {
	extractProviderSystemPrompt,
	parseOnOff,
	promptSectionBytes,
	pruneSessionCaptures,
	SESSION_CAPTURE_EPHEMERAL_TTL_MS,
	SESSION_CAPTURE_KEEP,
	SESSION_CAPTURE_TTL_MS,
	writeSessionCapture,
} from "./session-capture.ts";

test("on/off parsing treats only explicit on values as enabled", () => {
	assert.equal(parseOnOff("on"), true);
	assert.equal(parseOnOff(true), true);
	assert.equal(parseOnOff("true"), true);
	assert.equal(parseOnOff("off"), false);
	assert.equal(parseOnOff(false), false);
	assert.equal(parseOnOff(undefined), false);
});

test("extracts the actual system instruction from provider payload shapes", () => {
	assert.equal(extractProviderSystemPrompt({ instructions: "OpenAI instructions" }), "OpenAI instructions");
	assert.equal(
		extractProviderSystemPrompt({ system: [{ type: "text", text: "Anthropic system" }] }),
		"Anthropic system",
	);
	assert.equal(
		extractProviderSystemPrompt({
			messages: [
				{ role: "system", content: "System" },
				{ role: "developer", content: [{ type: "text", text: "Developer" }] },
				{ role: "user", content: "Ignore" },
			],
		}),
		"System\n\nDeveloper",
	);
	assert.equal(
		extractProviderSystemPrompt({ systemInstruction: { parts: [{ text: "Gemini system" }] } }),
		"Gemini system",
	);
});

test("session capture writes harness overlay and copied context files", () => {
	const dest = mkdtempSync(join(tmpdir(), "pi-easy-harness-test-"));
	const project = mkdtempSync(join(tmpdir(), "pi-easy-harness-project-"));
	const agentDir = join(project, "agent-home");
	try {
		mkdirSync(agentDir, { recursive: true });
		writeFileSync(join(agentDir, "AGENTS.md"), "Parent agents.\n");
		writeFileSync(join(project, "AGENTS.md"), "Project agents.\n");
		const root = writeSessionCapture({
			sessionId: "sess-1",
			cwd: project,
			trusted: false,
			harnessName: "codex",
			harnessOverlay: "<harness>overlay</harness>",
			effectiveSystemPrompt: "Pi base prompt.\n\n<harness>overlay</harness>",
			captureSubdir: "subagents/run-1/01-worker",
			model: { provider: "openai-codex", id: "gpt-5.6-luna" },
			thinking: "low",
			destRoot: dest,
			agentDir,
		});
		const capture = JSON.parse(readFileSync(join(root, "capture.json"), "utf8"));
		assert.equal(capture.harness, "codex");
		assert.equal(capture.model, "openai-codex/gpt-5.6-luna");
		assert.equal(capture.mergedPromptFile, "merged-prompt.md");
		assert.match(root, /sess-1\/subagents\/run-1\/01-worker$/);
		assert.equal(existsSync(join(root, "harness.md")), false);
		assert.equal(existsSync(join(root, "agents")), false);
		assert.equal(existsSync(join(root, "rules")), false);
		assert.match(readFileSync(join(root, "merged-prompt.md"), "utf8"), /Pi base prompt/);
		assert.equal(capture.sections.total, Buffer.byteLength("Pi base prompt.\n\n<harness>overlay</harness>", "utf8"));
		assert.ok(capture.sections.harness > 0);
		assert.ok(capture.sections.base > 0);
		assert.equal(capture.ephemeral, undefined);
	} finally {
		rmSync(dest, { recursive: true, force: true });
		rmSync(project, { recursive: true, force: true });
	}
});

