	for (const name of ["base", "tools", "guidelines", "docs", "skills", "cwd", "harness"]) {
		assert.ok((sections[name] ?? 0) > 0, name);
	}
	assert.equal(sections.base, Buffer.byteLength("You are an expert.\n", "utf8"));
});

