export function composeChildPrompt(input: {
	family: PromptFamily;
	rolePrompt: string;
	includesFamilyShared?: boolean;
	/** Append sources/common.md once. Ignored for pi-default and when the text already contains it. */
	common?: boolean;
	root?: string;
}): { family: PromptFamily; text: string; files: string[] } {
	const rolePrompt = input.rolePrompt.trim();
	const common = input.common && input.family !== "pi-default" ? commonBody(input.root).trim() : "";
	const finish = (text: string, files: string[]) => {
		if (!common) return { family: input.family, text, files };
		if (text.includes(common)) {
			return {
				family: input.family,
				text,
				files: files.includes("common.md") ? files : [...files, "common.md"],
			};
		}
		return {
			family: input.family,
			text: [text, common].filter(Boolean).join("\n"),
			files: [...files, "common.md"],
		};
	};
	if (input.includesFamilyShared || input.family === "pi-default") {
		return finish(rolePrompt, rolePrompt ? ["role"] : []);
	}
	const shared = familySharedBody(input.family, input.root).trim();
	if (!shared) {
		return finish(rolePrompt, rolePrompt ? ["role"] : []);
	}
	if (rolePrompt.includes(shared)) {
		return finish(rolePrompt, [`${input.family}/shared.md`, "role"]);
	}
	const text = [shared, rolePrompt].filter(Boolean).join("\n");
	return finish(text, rolePrompt ? [`${input.family}/shared.md`, "role"] : [`${input.family}/shared.md`]);
}

